// ─── Menu Config ─────────────────────────────────────────────────────────────

const MENU_ITEMS = [
  {
    key: 'dashboard',
    label: 'Dashboard',
    path: '/admin/dashboard',
    icon: (active) => <DashboardIcon active={active} />,
    children: [],
  },
  {
    key: 'products',
    label: 'Products',
    path: '/admin/products',
    icon: (active) => <VehicleIcon active={active} />,
    children: [
      { key: 'all-products',  label: 'All Products',  path: '/admin/products/all-products'  },
      { key: 'add-products',  label: 'Add Products',  path: '/admin/products/add-products'  },
    ],
  },
  {
    key: 'vehicles',
    label: 'Vehicles',
    path: '/admin/vehicles',
    icon: (active) => <VehicleIcon active={active} />,
    children: [
      { key: 'vehicles-info', label: 'Vehicles Info', path: '/admin/vehicles/vehicles-info' },
    ],
  },
  {
    key: 'new-vehicles',
    label: 'New Vehicles',
    path: '/admin/new-vehicles',
    icon: (active) => <VehicleIcon active={active} />,
    children: [
      { key: 'new-vehicles-info',    label: 'New Vehicles Info',    path: '/admin/new-vehicles/new-vehicles-info'    },
      { key: 'new-entry-vehicles',   label: 'New Entry Vehicles',   path: '/admin/new-vehicles/new-entry-vehicles'   },
    ],
  },
  {
    key: 'orders-management',
    label: 'Orders Management',
    path: '/admin/orders-management',
    icon: (active) => <VehicleIcon active={active} />,
    children: [
      { key: 'orders', label: 'Orders', path: '/admin/orders-management/orders' },
    ],
  },
];

// ─── Sidebar Component ────────────────────────────────────────────────────────

const AdminSidebar = () => {
  const navigate  = useNavigate();
  const location  = useLocation();
  const pathname  = location.pathname;
    const [openMenu, setOpenMenu] = useState(null);

  const isChildActive = (item) =>
    item.children.some((c) => pathname === c.path || pathname.startsWith(c.path));

  const isItemActive = (item) =>
    pathname === item.path || isChildActive(item);


//   useEffect(() => {
//   const activeItem = MENU_ITEMS.find(item =>
//     item.children.some(c => pathname.startsWith(c.path))
//   );
//   if (activeItem) {
//     setOpenMenu(activeItem.key);
//   }
// }, [pathname]);

  // const handleParentClick = (item) => {
  //   if (item.children.length > 0) {
     
  //     if (isChildActive(item)) {
  //       navigate(item.path);
  //     } else {
  //       navigate(item.children[0].path);
  //     }
  //   } else {
  //     navigate(item.path);
  //   }
  // };

  const handleParentClick = (item) => {
  if (item.children.length > 0) {
    if (openMenu === item.key) {
      // 👉 same menu click → close
      setOpenMenu(null);
      navigate(item.path);
    } else {
      // 👉 open menu
      setOpenMenu(item.key);
      navigate(item.children[0].path);
    }
  } else {
    navigate(item.path);
  }
};

  return (
    <div className="AdminPanelHome-contentLeft">
      {MENU_ITEMS.map((item) => {
        const active      = isItemActive(item);
        // const submenuOpen = isChildActive(item);
        const submenuOpen = openMenu === item.key;

        return (
          <div key={item.key}>

            {/* ── Parent Menu Row ── */}
            <div
              className={`adminHeadings ${active ? 'active' : ''}`}
              onClick={() => handleParentClick(item)}
            >
              <div className="sideImageHeading">
                {item.icon(active)}
                {item.label}
              </div>
              {item.children.length > 0 && (
                <i className={`fas fa-chevron-${submenuOpen ? 'up' : 'down'} ml-2`} />
              )}
            </div>

            {/* ── Submenu ── */}
            {item.children.length > 0 && submenuOpen && (
              <div className="subcategory-list pl-6">
                {item.children.map((child) => (
                  <div
                    key={child.key}
                    className={`subcategory-item ${pathname === child.path ? 'active' : ''}`}
                    onClick={() => navigate(child.path)}
                  >
                    {child.label}
                  </div>
                ))}
              </div>
            )}

          </div>
        );
      })}
    </div>
  );
};

export default AdminSidebar;
